const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define lake geometries (points with buffers)
  const dorsoidongCo = ee.Geometry.Point([88.1, 33.1]).buffer(500);
  const chibzhangCo = ee.Geometry.Point([88.5, 33.5]).buffer(500);

  // Function to mask clouds and water
  function maskCloudsAndWater(image) {
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0); // Cloud bit
    const cloudShadowMask = qa.bitwiseAnd(1 << 4).eq(0); // Cloud shadow bit

    // Water mask (NDWI > 0)
    const ndwi = image.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
    const waterMask = ndwi.gt(0);

    return image.updateMask(cloudMask.and(cloudShadowMask).and(waterMask))
                .addBands(ndwi);
  }

  // Get Landsat 5 collection for the specific date
  const startDate = '1987-10-12';
  const endDate = '1987-10-13';

  const landsatCol = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterDate(startDate, endDate)
    .filterBounds(dorsoidongCo.union(chibzhangCo))
    .map(maskCloudsAndWater);

  // Check if collection is empty
  const colSize = landsatCol.size().getInfo();
  if (colSize === 0) {
    print("No Landsat 5 images found for 1987-10-12");
    print("<answer>C1</answer>");
    return;
  }

  // Get the first image
  const image = landsatCol.first();

  // Extract blue band (B1) reflectance for both lakes
  const blueBand = 'SR_B1';

  // Calculate mean blue reflectance for Dorsoidong Co
  const dorsoidongStats = image.select(blueBand).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: dorsoidongCo,
    scale: 30,
    maxPixels: 1e9
  });

  // Calculate mean blue reflectance for Chibzhang Co
  const chibzhangStats = image.select(blueBand).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: chibzhangCo,
    scale: 30,
    maxPixels: 1e9
  });

  const dorsoidongMean = dorsoidongStats.get('mean').getInfo();
  const dorsoidongCount = dorsoidongStats.get('count').getInfo();
  const chibzhangMean = chibzhangStats.get('mean').getInfo();
  const chibzhangCount = chibzhangStats.get('count').getInfo();

  print(`Dorsoidong Co: Mean Blue=${dorsoidongMean?.toFixed(4)}, Pixels=${dorsoidongCount}`);
  print(`Chibzhang Co: Mean Blue=${chibzhangMean?.toFixed(4)}, Pixels=${chibzhangCount}`);

  // Check for valid pixels
  if (dorsoidongCount === 0 || chibzhangCount === 0) {
    print("No valid water pixels after masking");
    print("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (dorsoidongMean === null || chibzhangMean === null || 
      isNaN(dorsoidongMean) || isNaN(chibzhangMean)) {
    print("Calculation failed - invalid reflectance values");
    print("<answer>C3</answer>");
    return;
  }

  // Compare blue reflectance (higher = lighter color)
  if (dorsoidongMean > chibzhangMean) {
    print("Dorsoidong Co is lighter (higher blue reflectance)");
    print("<answer>A</answer>");
  } else {
    print("Chibzhang Co is lighter or equal (higher/equal blue reflectance)");
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
